package rs.zivke.seedtag.core

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

class SeedBoxTest {

    private fun hex(s: String) = ByteArray(s.length / 2) { s.substring(2 * it, 2 * it + 2).toInt(16).toByte() }

    private data class Vec(val password: String, val entropy: ByteArray, val salt: ByteArray, val nonce: ByteArray, val b64: String, val fp: String)

    /** Generated by tools/seedtag.py with fixed salt/nonce – proves byte-for-byte compatibility. */
    private val vectors by lazy {
        javaClass.getResource("/seedtag-v1-vectors.tsv")!!.readText().lines().filter { it.isNotBlank() }.map {
            val c = it.split("\t")
            Vec(String(hex(c[0]), Charsets.UTF_8), hex(c[1]), hex(c[2]), hex(c[3]), c[4], c[5])
        }
    }

    @Test
    fun sealMatchesPython() {
        assertTrue(vectors.size >= 5)
        for (v in vectors) {
            val blob = SeedBox.seal(v.entropy, v.password.toCharArray(), v.salt, v.nonce)
            assertEquals(v.b64, SeedBox.toBase64(blob))
        }
    }

    @Test
    fun openPythonBlobs() {
        for (v in vectors) {
            val e = SeedBox.open(SeedBox.fromBase64(v.b64), v.password.toCharArray())
            assertArrayEquals(v.entropy, e)
            assertEquals(v.fp, SeedBox.fingerprint(e))
        }
    }

    @Test
    fun wrongPassword() {
        val v = vectors.first()
        try {
            SeedBox.open(SeedBox.fromBase64(v.b64), "nope".toCharArray()); fail()
        } catch (e: SeedTagException.WrongPassword) { }
    }

    @Test
    fun tamperedBlobFails() {
        val v = vectors.first()
        for (pos in listOf(0, 5, 20, 40, 76)) {
            val blob = SeedBox.fromBase64(v.b64)
            blob[pos] = (blob[pos].toInt() xor 1).toByte()
            try {
                SeedBox.open(blob, v.password.toCharArray()); fail("pos $pos")
            } catch (e: SeedTagException) { }
        }
    }

    @Test
    fun malformed() {
        for (bad in listOf("", "!!!", "AQ==", "Ag" + "A".repeat(100))) {
            try {
                SeedBox.open(SeedBox.fromBase64(bad), "x".toCharArray()); fail(bad)
            } catch (e: SeedTagException) { }
        }
    }

    @Test
    fun randomRoundTripAndFits137ByteTag() {
        val e = ByteArray(32) { it.toByte() }
        val blob = SeedBox.seal(e, "pw".toCharArray())
        assertEquals(77, blob.size)
        val text = SeedBox.toBase64(blob)
        assertEquals(104, text.length)
        // NDEF TLV (2) + record + terminator (1) must fit the Ultralight C's 137 bytes
        assertTrue(2 + NdefText.messageSize(text) + 1 <= 137)
        assertArrayEquals(e, SeedBox.open(blob, "pw".toCharArray()))
        // fresh salt/nonce every time
        assertTrue(SeedBox.toBase64(SeedBox.seal(e, "pw".toCharArray())) != text)
    }

    @Test
    fun backupSizes() {
        for (v in vectors) {
            val words = v.entropy.size * 3 / 4
            assertEquals(NdefText.messageSize(v.b64), SeedBox.ndefBytesFor(words))
        }
        assertEquals(91, SeedBox.ndefBytesFor(12))
        assertEquals(111, SeedBox.ndefBytesFor(24))
        assertEquals(24, SeedBox.maxWordsFor(137))
        assertEquals(24, SeedBox.maxWordsFor(111))
        assertEquals(21, SeedBox.maxWordsFor(110))
        assertEquals(12, SeedBox.maxWordsFor(91))
        assertEquals(null, SeedBox.maxWordsFor(90))
        assertEquals(null, SeedBox.maxWordsFor(46))
    }

    @Test
    fun ndefTextRoundTrip() {
        val t = vectors.first().b64
        assertEquals(t, NdefText.decodePayload(NdefText.encodePayload(t)))
    }

    @Test
    fun passphrase() {
        val p = Passphrase.generate()
        assertEquals(7, String(p).split(" ").size)
        assertEquals(77, Passphrase.estimateBits(p, random = true))
        assertTrue(Passphrase.estimateBits("hunter2".toCharArray()) < 40)
    }

    @Test
    fun kindOfTagText() {
        val v1 = vectors[0].b64
        val blob = SeedBox.fromBase64(v1)
        fun withFirst(b: Int) = SeedBox.toBase64(blob.copyOf().also { it[0] = b.toByte() })
        assertEquals(SeedBox.Kind.Current, SeedBox.kindOf(v1))
        assertEquals(SeedBox.Kind.Newer, SeedBox.kindOf(withFirst(0x02)))
        assertEquals(SeedBox.Kind.Newer, SeedBox.kindOf(withFirst(SeedBox.MAX_FUTURE_VERSION)))
        assertEquals(SeedBox.Kind.NotBackup, SeedBox.kindOf(withFirst(0x00)))
        assertEquals(SeedBox.Kind.NotBackup, SeedBox.kindOf(withFirst(0x10)))
        assertEquals(SeedBox.Kind.NotBackup, SeedBox.kindOf(SeedBox.toBase64(blob.copyOf(40))))
        assertEquals(SeedBox.Kind.NotBackup, SeedBox.kindOf("https://example.com"))
        assertEquals(SeedBox.Kind.NotBackup, SeedBox.kindOf(null))
    }

    @Test
    fun newerFormatSaysSo() {
        val v = vectors[0]
        val blob = SeedBox.fromBase64(v.b64).also { it[0] = 0x02 }
        try {
            SeedBox.open(blob, v.password.toCharArray())
            fail("opened a v2 blob")
        } catch (e: SeedTagException.UnsupportedVersion) {
            assertTrue(e.message!!, e.message!!.contains("newer version of SeedTag"))
        }
    }
}
